import * as React from "react";
import { cn } from "../../lib/utils";

type ButtonVariant = "default" | "outline" | "ghost";
type ButtonSize = "sm" | "md" | "lg";

const variantClass: Record<ButtonVariant, string> = {
  default:
    "border border-matrix-neon/40 bg-matrix-neon/15 text-matrix-text hover:border-matrix-neon hover:bg-matrix-neon/20 focus-visible:ring-matrix-neon/40",
  outline:
    "border border-matrix-line bg-black/20 text-matrix-text hover:border-matrix-cyan/60 hover:bg-matrix-cyan/10 focus-visible:ring-matrix-cyan/30",
  ghost:
    "border border-transparent bg-transparent text-matrix-muted hover:border-matrix-line hover:text-matrix-text focus-visible:ring-matrix-line"
};

const sizeClass: Record<ButtonSize, string> = {
  sm: "h-9 px-3 text-xs",
  md: "h-10 px-4 text-sm",
  lg: "h-11 px-5 text-sm"
};

export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: ButtonVariant;
  size?: ButtonSize;
};

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = "default", size = "md", type = "button", ...props }, ref) => {
    return (
      <button
        ref={ref}
        type={type}
        className={cn(
          "inline-flex items-center justify-center gap-2 rounded-md font-medium transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-0 disabled:pointer-events-none disabled:opacity-50",
          variantClass[variant],
          sizeClass[size],
          className
        )}
        {...props}
      />
    );
  }
);

Button.displayName = "Button";

export { Button };
