import * as React from "react";
import { cn } from "../../lib/utils";

type BadgeVariant = "default" | "muted" | "accent";

const styles: Record<BadgeVariant, string> = {
  default: "border-matrix-neon/35 bg-matrix-neon/12 text-matrix-neon",
  muted: "border-matrix-line bg-black/25 text-matrix-muted",
  accent: "border-matrix-cyan/35 bg-matrix-cyan/12 text-matrix-cyan"
};

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant;
}

export function Badge({ className, variant = "default", ...props }: BadgeProps): JSX.Element {
  return (
    <span
      className={cn(
        "inline-flex items-center rounded-full border px-2.5 py-1 text-xs font-medium",
        styles[variant],
        className
      )}
      {...props}
    />
  );
}
