import * as React from "react";
import { cn } from "../../lib/utils";

type DropdownMenuContextValue = {
  open: boolean;
  setOpen: (value: boolean) => void;
  rootRef: React.RefObject<HTMLDivElement | null>;
};

const DropdownMenuContext = React.createContext<DropdownMenuContextValue | null>(null);

function useDropdownMenuContext(): DropdownMenuContextValue {
  const context = React.useContext(DropdownMenuContext);
  if (!context) {
    throw new Error("Dropdown components must be used inside <DropdownMenu />");
  }
  return context;
}

export function DropdownMenu({ children }: { children: React.ReactNode }): JSX.Element {
  const [open, setOpen] = React.useState(false);
  const rootRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const onClickOutside = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false);
      }
    };

    document.addEventListener("mousedown", onClickOutside);
    return () => document.removeEventListener("mousedown", onClickOutside);
  }, []);

  return (
    <DropdownMenuContext.Provider value={{ open, setOpen, rootRef }}>
      <div ref={rootRef} className="relative inline-flex">
        {children}
      </div>
    </DropdownMenuContext.Provider>
  );
}

interface DropdownMenuTriggerProps {
  children: React.ReactElement;
}

export function DropdownMenuTrigger({ children }: DropdownMenuTriggerProps): JSX.Element {
  const { open, setOpen } = useDropdownMenuContext();
  return React.cloneElement(children, {
    onClick: (event: React.MouseEvent) => {
      children.props.onClick?.(event);
      setOpen(!open);
    },
    "aria-expanded": open,
    "aria-haspopup": "menu"
  });
}

export function DropdownMenuContent({ className, ...props }: React.HTMLAttributes<HTMLDivElement>): JSX.Element | null {
  const { open } = useDropdownMenuContext();
  if (!open) {
    return null;
  }

  return (
    <div
      role="menu"
      className={cn(
        "absolute right-0 top-[calc(100%+8px)] z-30 min-w-[180px] rounded-xl border border-matrix-line bg-[#071616] p-1 shadow-card",
        className
      )}
      {...props}
    />
  );
}

export function DropdownMenuItem({ className, ...props }: React.HTMLAttributes<HTMLDivElement>): JSX.Element {
  return (
    <div
      role="menuitem"
      className={cn(
        "cursor-pointer rounded-md px-3 py-2 text-sm text-matrix-muted transition-colors hover:bg-matrix-neon/12 hover:text-matrix-text",
        className
      )}
      {...props}
    />
  );
}
