import { cn } from "../lib/utils";

type SectionHeaderProps = {
  kicker?: string;
  title: string;
  subtitle?: string;
  className?: string;
};

function SectionHeader({ kicker, title, subtitle, className }: SectionHeaderProps): JSX.Element {
  return (
    <header className={cn("max-w-3xl", className)}>
      {kicker ? (
        <p className="matrix-heading text-xs uppercase tracking-[0.2em] text-matrix-cyan">{kicker}</p>
      ) : null}
      <h2 className="matrix-heading mt-2 text-3xl font-semibold text-matrix-text sm:text-4xl">{title}</h2>
      {subtitle ? <p className="mt-3 text-sm leading-7 text-matrix-muted sm:text-base">{subtitle}</p> : null}
    </header>
  );
}

export default SectionHeader;
