import * as React from "react";
import { Tech } from "../data/tech";
import { cn } from "../lib/utils";
import { Badge } from "./ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "./ui/tabs";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "./ui/tooltip";

type TechMatrixProps = {
  tech: Tech[];
};

type MatrixFilter = "All" | Tech["category"];

const filters: MatrixFilter[] = ["All", "Frontend", "Backend", "DevOps", "DB", "Tools"];

function TechMatrix({ tech }: TechMatrixProps): JSX.Element {
  const [activeFilter, setActiveFilter] = React.useState<MatrixFilter>("All");
  const [activeIndex, setActiveIndex] = React.useState<number | null>(null);

  const visible = React.useMemo(
    () => (activeFilter === "All" ? tech : tech.filter((item) => item.category === activeFilter)),
    [activeFilter, tech]
  );

  const distanceFromActive = (index: number): number => {
    if (activeIndex === null) {
      return 99;
    }
    return Math.abs(index - activeIndex);
  };

  return (
    <div className="matrix-panel mt-6 rounded-2xl p-4 sm:p-6">
      <Tabs defaultValue="All" value={activeFilter} onValueChange={(value) => setActiveFilter(value as MatrixFilter)}>
        <TabsList className="flex flex-wrap gap-1">
          {filters.map((filter) => (
            <TabsTrigger key={filter} value={filter}>
              {filter}
            </TabsTrigger>
          ))}
        </TabsList>

        {filters.map((filter) => (
          <TabsContent key={filter} value={filter}>
            <TooltipProvider>
              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                {visible.map((item, index) => {
                  const distance = distanceFromActive(index);
                  const isActive = activeIndex === index;

                  const waveClass =
                    distance === 0
                      ? "scale-[1.02] border-matrix-neon/70 bg-matrix-neon/15"
                      : distance === 1
                      ? "border-matrix-neon/40 bg-matrix-neon/8"
                      : distance === 2
                      ? "border-matrix-line/80 bg-black/25"
                      : "";

                  return (
                    <Tooltip key={`${item.name}-${item.category}`}>
                      <TooltipTrigger>
                        <button
                          type="button"
                          className={cn(
                            "group glow-hover relative flex min-h-[74px] w-full flex-col items-start justify-between rounded-xl border border-matrix-line bg-black/20 p-3 text-left",
                            waveClass,
                            item.highlight && "shadow-[0_0_0_1px_rgba(49,241,139,0.3),0_0_16px_rgba(49,241,139,0.14)]"
                          )}
                          aria-label={`${item.name} en ${item.category}. Nivel ${item.level ?? "Intermediate"}.`}
                          onMouseEnter={() => setActiveIndex(index)}
                          onMouseLeave={() => setActiveIndex(null)}
                          onFocus={() => setActiveIndex(index)}
                          onBlur={() => setActiveIndex(null)}
                          onClick={() => setActiveIndex((prev) => (prev === index ? null : index))}
                          onKeyDown={(event) => {
                            if (event.key === "Enter" || event.key === " ") {
                              event.preventDefault();
                              setActiveIndex((prev) => (prev === index ? null : index));
                            }
                          }}
                        >
                          <span className="matrix-heading text-sm text-matrix-text">{item.name}</span>
                          <div className="mt-2 flex w-full items-center justify-between gap-2">
                            <Badge variant={item.highlight ? "default" : "muted"}>{item.category}</Badge>
                            <span className="text-xs text-matrix-muted">{item.level ?? "Intermediate"}</span>
                          </div>
                          <span
                            aria-hidden="true"
                            className={cn(
                              "pointer-events-none absolute inset-0 rounded-xl opacity-0 transition-opacity",
                              isActive && "opacity-100",
                              "bg-[radial-gradient(circle_at_center,rgba(49,241,139,0.14),transparent_62%)]"
                            )}
                          />
                        </button>
                      </TooltipTrigger>
                      <TooltipContent>
                        {item.name}: {item.level ?? "Intermediate"} - uso en {item.category}
                      </TooltipContent>
                    </Tooltip>
                  );
                })}
              </div>
            </TooltipProvider>
          </TabsContent>
        ))}
      </Tabs>
    </div>
  );
}

export default TechMatrix;
