import { Project } from "../data/projects";
import { Badge } from "./ui/badge";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle
} from "./ui/dialog";

type ProjectModalProps = {
  project: Project | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
};

function ProjectModal({ project, open, onOpenChange }: ProjectModalProps): JSX.Element {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        {project ? (
          <>
            <DialogHeader>
              <DialogTitle className="matrix-heading">{project.title}</DialogTitle>
              <DialogDescription>{project.summary}</DialogDescription>
            </DialogHeader>

            <img
              src={project.thumbnail}
              alt={`Miniatura del proyecto ${project.title}`}
              className="mt-4 h-56 w-full rounded-xl border border-matrix-line object-cover"
              loading="lazy"
            />

            <div className="mt-5 grid gap-5 md:grid-cols-2">
              <section>
                <h3 className="matrix-heading text-sm uppercase tracking-[0.15em] text-matrix-cyan">Contexto</h3>
                <p className="mt-2 text-sm leading-7 text-matrix-muted">{project.context}</p>
              </section>
              <section>
                <h3 className="matrix-heading text-sm uppercase tracking-[0.15em] text-matrix-cyan">Mi rol</h3>
                <p className="mt-2 text-sm leading-7 text-matrix-muted">{project.role}</p>
              </section>
            </div>

            <section className="mt-5">
              <h3 className="matrix-heading text-sm uppercase tracking-[0.15em] text-matrix-cyan">Resultados</h3>
              <ul className="mt-2 grid gap-2 text-sm text-matrix-muted sm:grid-cols-3">
                {project.impact.map((metric) => (
                  <li key={metric} className="rounded-lg border border-matrix-line bg-black/20 px-3 py-2">
                    {metric}
                  </li>
                ))}
              </ul>
            </section>

            <section className="mt-5">
              <h3 className="matrix-heading text-sm uppercase tracking-[0.15em] text-matrix-cyan">Retos tecnicos</h3>
              <ul className="mt-2 space-y-2 text-sm text-matrix-muted">
                {project.challenges.map((challenge) => (
                  <li key={challenge}>• {challenge}</li>
                ))}
              </ul>
            </section>

            <section className="mt-5">
              <h3 className="matrix-heading text-sm uppercase tracking-[0.15em] text-matrix-cyan">Stack</h3>
              <div className="mt-2 flex flex-wrap gap-2">
                {project.stack.map((item) => (
                  <Badge key={item} variant="muted">
                    {item}
                  </Badge>
                ))}
              </div>
            </section>

            <DialogFooter>
              {project.links.demo ? (
                <a
                  href={project.links.demo}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex h-10 items-center rounded-md border border-matrix-neon/45 bg-matrix-neon/12 px-4 text-sm"
                >
                  Demo
                </a>
              ) : null}
              {project.links.github ? (
                <a
                  href={project.links.github}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex h-10 items-center rounded-md border border-matrix-line px-4 text-sm"
                >
                  GitHub
                </a>
              ) : null}
              {project.links.caseStudy ? (
                <a
                  href={project.links.caseStudy}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex h-10 items-center rounded-md border border-matrix-cyan/35 bg-matrix-cyan/10 px-4 text-sm"
                >
                  Case Study
                </a>
              ) : null}
              <DialogClose>Cerrar</DialogClose>
            </DialogFooter>
          </>
        ) : null}
      </DialogContent>
    </Dialog>
  );
}

export default ProjectModal;
