import * as React from "react";
import { cn } from "../../lib/utils";

type TiltSurfaceProps = {
  children: React.ReactNode;
  className?: string;
};

function TiltSurface({ children, className }: TiltSurfaceProps): JSX.Element {
  const ref = React.useRef<HTMLDivElement>(null);
  const [transform, setTransform] = React.useState("perspective(1000px) rotateX(0deg) rotateY(0deg)");

  const handleMove = (event: React.MouseEvent<HTMLDivElement>) => {
    if (typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return;
    }
    const element = ref.current;
    if (!element) {
      return;
    }

    const rect = element.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const rotateY = (x / rect.width - 0.5) * 8;
    const rotateX = (y / rect.height - 0.5) * -8;

    setTransform(`perspective(1000px) rotateX(${rotateX.toFixed(2)}deg) rotateY(${rotateY.toFixed(2)}deg)`);
  };

  return (
    <div
      ref={ref}
      className={cn("transition-transform duration-200 ease-out", className)}
      style={{ transform }}
      onMouseMove={handleMove}
      onMouseLeave={() => setTransform("perspective(1000px) rotateX(0deg) rotateY(0deg)")}
    >
      {children}
    </div>
  );
}

export default TiltSurface;
