import * as React from "react";
import { Button } from "./ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "./ui/dropdown-menu";

type NavItem = {
  id: string;
  label: string;
};

type NavbarProps = {
  items: NavItem[];
};

function Navbar({ items }: NavbarProps): JSX.Element {
  const [activeId, setActiveId] = React.useState(items[0]?.id ?? "hero");

  React.useEffect(() => {
    const sections = items
      .map((item) => document.getElementById(item.id))
      .filter((section): section is HTMLElement => section !== null);

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveId(entry.target.id);
          }
        });
      },
      { rootMargin: "-40% 0px -45% 0px", threshold: 0 }
    );

    sections.forEach((section) => observer.observe(section));
    return () => observer.disconnect();
  }, [items]);

  return (
    <header className="fixed inset-x-0 top-0 z-40 border-b border-matrix-line/70 bg-[#040808]/85 backdrop-blur-md">
      <div className="mx-auto flex h-16 max-w-6xl items-center justify-between px-4 sm:px-6 lg:px-8">
        <a href="#hero" className="matrix-heading text-sm font-semibold uppercase tracking-[0.2em] text-matrix-neon">
          CodeByAxel
        </a>

        <nav aria-label="Principal" className="hidden items-center gap-1 md:flex">
          {items.map((item) => (
            <a
              key={item.id}
              href={`#${item.id}`}
              className={`rounded-md px-3 py-2 text-sm transition-colors ${
                activeId === item.id ? "bg-matrix-neon/20 text-matrix-text" : "text-matrix-muted hover:text-matrix-text"
              }`}
            >
              {item.label}
            </a>
          ))}
        </nav>

        <div className="flex items-center gap-2">
          <DropdownMenu>
            <DropdownMenuTrigger>
              <Button variant="outline" size="sm" aria-label="Abrir enlaces rapidos">
                Links
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent>
              <DropdownMenuItem>
                <a href="https://github.com/CodeByAxel" target="_blank" rel="noreferrer">
                  GitHub
                </a>
              </DropdownMenuItem>
              <DropdownMenuItem>
                <a href="https://www.linkedin.com/in/axel-ortiz-4a2240194/" target="_blank" rel="noreferrer">
                  LinkedIn
                </a>
              </DropdownMenuItem>
              <DropdownMenuItem>
                <a href="mailto:axelortiz.mesa@gmail.com">Email</a>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>

          <a
            href="#contact"
            className="inline-flex h-9 items-center rounded-md border border-matrix-neon/40 bg-matrix-neon/15 px-3 text-xs font-medium text-matrix-text transition hover:border-matrix-neon hover:bg-matrix-neon/20"
          >
            Hire me
          </a>
        </div>
      </div>
    </header>
  );
}

export default Navbar;
