import * as React from "react";

type TextScrambleProps = {
  texts: string[];
  className?: string;
  speed?: number;
};

const glyphs = "01<>/[]{}+*";

function getReducedMotionPreference(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
    return false;
  }
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function TextScramble({ texts, className, speed = 40 }: TextScrambleProps): JSX.Element {
  const [display, setDisplay] = React.useState(texts[0] ?? "");
  const [index, setIndex] = React.useState(0);
  const reducedMotion = React.useMemo(() => getReducedMotionPreference(), []);

  React.useEffect(() => {
    if (!texts.length) {
      return;
    }

    if (reducedMotion) {
      const reducedTimer = window.setInterval(() => {
        setIndex((prev) => (prev + 1) % texts.length);
      }, 2400);
      return () => window.clearInterval(reducedTimer);
    }

    let frame = 0;
    const timer = window.setInterval(() => {
      const target = texts[index] ?? "";
      const next = target
        .split("")
        .map((char, charIndex) => {
          if (charIndex < frame) {
            return target[charIndex];
          }
          return glyphs[Math.floor(Math.random() * glyphs.length)];
        })
        .join("");

      setDisplay(next);
      frame += 1;

      if (frame > target.length) {
        window.clearInterval(timer);
        setDisplay(target);
        window.setTimeout(() => {
          setIndex((prev) => (prev + 1) % texts.length);
        }, 1800);
      }
    }, speed);

    return () => window.clearInterval(timer);
  }, [index, reducedMotion, speed, texts]);

  return <span className={className}>{display}</span>;
}

export default TextScramble;
