import * as React from "react";
import LaserFlow from "./effects/LaserFlow";

type MatrixLayer = {
  className: string;
};

const layers: MatrixLayer[] = [{ className: "opacity-40" }, { className: "opacity-25" }];

function MatrixBackground(): JSX.Element {
  const [reducedMotion, setReducedMotion] = React.useState(false);

  React.useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  return (
    <div aria-hidden="true" className="pointer-events-none absolute inset-0 z-0 overflow-hidden">
      {!reducedMotion ? (
        <div className="absolute inset-0 opacity-55">
          <LaserFlow
            className="h-full w-full"
            color="#31f18b"
            wispDensity={0.9}
            flowSpeed={0.28}
            verticalSizing={12}
            horizontalSizing={0.9}
            fogIntensity={0.25}
            wispIntensity={3.8}
            flowStrength={0.18}
            mouseTiltStrength={0.012}
            horizontalBeamOffset={0}
            verticalBeamOffset={0}
          />
        </div>
      ) : null}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_20%,rgba(49,241,139,0.09),transparent_40%),radial-gradient(circle_at_80%_10%,rgba(54,216,255,0.08),transparent_35%),radial-gradient(circle_at_50%_80%,rgba(142,125,255,0.06),transparent_40%)]" />
      <div className="absolute inset-0 bg-matrix-grid bg-[size:34px_34px] opacity-35" />
      {layers.map((layer, index) => (
        <div
          key={index}
          className={`absolute inset-0 bg-[linear-gradient(180deg,transparent_0%,rgba(49,241,139,0.04)_20%,transparent_45%,transparent_55%,rgba(49,241,139,0.04)_80%,transparent_100%)] ${layer.className} ${
            reducedMotion ? "" : "animate-drift"
          }`}
        />
      ))}
      <div className="absolute inset-0 opacity-20 [background:repeating-linear-gradient(180deg,transparent,transparent_3px,rgba(49,241,139,0.05)_4px)]" />
      {!reducedMotion ? <div className="absolute inset-0 opacity-20 animate-scan [background:linear-gradient(180deg,transparent,rgba(49,241,139,0.2),transparent)]" /> : null}
    </div>
  );
}

export default MatrixBackground;
