import * as React from "react";
import { cn } from "../../lib/utils";

type TooltipContextValue = {
  open: boolean;
  setOpen: (value: boolean) => void;
};

const TooltipContext = React.createContext<TooltipContextValue | null>(null);

export function TooltipProvider({ children }: { children: React.ReactNode }): JSX.Element {
  return <>{children}</>;
}

export function Tooltip({ children }: { children: React.ReactNode }): JSX.Element {
  const [open, setOpen] = React.useState(false);
  return (
    <TooltipContext.Provider value={{ open, setOpen }}>
      <span className="relative inline-flex">{children}</span>
    </TooltipContext.Provider>
  );
}

interface TooltipTriggerProps {
  children: React.ReactElement;
}

export function TooltipTrigger({ children }: TooltipTriggerProps): JSX.Element {
  const context = React.useContext(TooltipContext);
  if (!context) {
    throw new Error("TooltipTrigger must be inside Tooltip");
  }

  return React.cloneElement(children, {
    onMouseEnter: (event: React.MouseEvent) => {
      children.props.onMouseEnter?.(event);
      context.setOpen(true);
    },
    onMouseLeave: (event: React.MouseEvent) => {
      children.props.onMouseLeave?.(event);
      context.setOpen(false);
    },
    onFocus: (event: React.FocusEvent) => {
      children.props.onFocus?.(event);
      context.setOpen(true);
    },
    onBlur: (event: React.FocusEvent) => {
      children.props.onBlur?.(event);
      context.setOpen(false);
    }
  });
}

export function TooltipContent({ className, children }: React.HTMLAttributes<HTMLDivElement>): JSX.Element | null {
  const context = React.useContext(TooltipContext);
  if (!context?.open) {
    return null;
  }

  return (
    <span
      role="tooltip"
      className={cn(
        "absolute left-1/2 top-[calc(100%+8px)] z-20 w-max -translate-x-1/2 rounded-md border border-matrix-cyan/35 bg-[#071616] px-2 py-1 text-[11px] text-matrix-text shadow-lg",
        className
      )}
    >
      {children}
    </span>
  );
}
