import * as React from "react";
import { Button } from "./ui/button";

type FormState = {
  name: string;
  email: string;
  message: string;
};

type FormErrors = Partial<Record<keyof FormState, string>>;

const initialState: FormState = {
  name: "",
  email: "",
  message: ""
};

function ContactSection(): JSX.Element {
  const [form, setForm] = React.useState<FormState>(initialState);
  const [errors, setErrors] = React.useState<FormErrors>({});
  const [submitted, setSubmitted] = React.useState(false);

  const validate = (state: FormState): FormErrors => {
    const nextErrors: FormErrors = {};

    if (!state.name.trim()) {
      nextErrors.name = "Tu nombre es obligatorio.";
    }

    if (!/^\S+@\S+\.\S+$/.test(state.email)) {
      nextErrors.email = "Introduce un email valido.";
    }

    if (state.message.trim().length < 15) {
      nextErrors.message = "Explica el contexto en al menos 15 caracteres.";
    }

    return nextErrors;
  };

  const onChange = (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = event.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const onSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const nextErrors = validate(form);
    setErrors(nextErrors);

    if (Object.keys(nextErrors).length > 0) {
      return;
    }

    setSubmitted(true);

    const subject = encodeURIComponent(`Consulta portfolio de ${form.name}`);
    const body = encodeURIComponent(`${form.message}\n\nContacto: ${form.email}`);
    window.location.href = `mailto:axelortiz.mesa@gmail.com?subject=${subject}&body=${body}`;

    setForm(initialState);
  };

  return (
    <div className="mt-6 grid gap-6 lg:grid-cols-[1.15fr_0.85fr]">
      <form onSubmit={onSubmit} className="matrix-panel rounded-2xl p-6" noValidate>
        <div className="grid gap-4">
          <label className="text-sm text-matrix-muted" htmlFor="name">
            Nombre
          </label>
          <input
            id="name"
            name="name"
            type="text"
            value={form.name}
            onChange={onChange}
            className="rounded-lg border border-matrix-line bg-black/25 px-3 py-2 text-sm text-matrix-text outline-none ring-matrix-neon/35 focus:ring-2"
            aria-invalid={Boolean(errors.name)}
            aria-describedby={errors.name ? "name-error" : undefined}
          />
          {errors.name ? (
            <p id="name-error" className="text-xs text-red-300">
              {errors.name}
            </p>
          ) : null}

          <label className="text-sm text-matrix-muted" htmlFor="email">
            Email
          </label>
          <input
            id="email"
            name="email"
            type="email"
            value={form.email}
            onChange={onChange}
            className="rounded-lg border border-matrix-line bg-black/25 px-3 py-2 text-sm text-matrix-text outline-none ring-matrix-neon/35 focus:ring-2"
            aria-invalid={Boolean(errors.email)}
            aria-describedby={errors.email ? "email-error" : undefined}
          />
          {errors.email ? (
            <p id="email-error" className="text-xs text-red-300">
              {errors.email}
            </p>
          ) : null}

          <label className="text-sm text-matrix-muted" htmlFor="message">
            Mensaje
          </label>
          <textarea
            id="message"
            name="message"
            rows={5}
            value={form.message}
            onChange={onChange}
            className="rounded-lg border border-matrix-line bg-black/25 px-3 py-2 text-sm text-matrix-text outline-none ring-matrix-neon/35 focus:ring-2"
            aria-invalid={Boolean(errors.message)}
            aria-describedby={errors.message ? "message-error" : undefined}
          />
          {errors.message ? (
            <p id="message-error" className="text-xs text-red-300">
              {errors.message}
            </p>
          ) : null}

          <div className="mt-2 flex items-center gap-3">
            <Button type="submit">Enviar mensaje</Button>
            <a
              href="mailto:axelortiz.mesa@gmail.com"
              className="inline-flex h-10 items-center rounded-md border border-matrix-line px-3 text-sm text-matrix-muted"
            >
              Email directo
            </a>
          </div>
          {submitted ? <p className="text-xs text-matrix-neon">Mensaje preparado. Te respondo en menos de 24h.</p> : null}
        </div>
      </form>

      <aside className="matrix-panel rounded-2xl p-6">
        <h3 className="matrix-heading text-lg text-matrix-text">Canales directos</h3>
        <p className="mt-2 text-sm leading-7 text-matrix-muted">
          Si estas evaluando perfiles para frontend/full-stack, aqui tienes acceso rapido a mi trabajo y contacto.
        </p>
        <div className="mt-5 flex flex-col gap-3 text-sm">
          <a
            href="https://github.com/CodeByAxel"
            target="_blank"
            rel="noreferrer"
            className="rounded-lg border border-matrix-line px-3 py-2 text-matrix-muted transition hover:border-matrix-neon/45 hover:text-matrix-text"
          >
            GitHub: github.com/CodeByAxel
          </a>
          <a
            href="https://www.linkedin.com/in/axel-ortiz-4a2240194/"
            target="_blank"
            rel="noreferrer"
            className="rounded-lg border border-matrix-line px-3 py-2 text-matrix-muted transition hover:border-matrix-cyan/45 hover:text-matrix-text"
          >
            LinkedIn: Axel Ortiz
          </a>
          <a
            href="mailto:axelortiz.mesa@gmail.com"
            className="rounded-lg border border-matrix-line px-3 py-2 text-matrix-muted transition hover:border-matrix-neon/45 hover:text-matrix-text"
          >
            axelortiz.mesa@gmail.com
          </a>
        </div>
      </aside>
    </div>
  );
}

export default ContactSection;
