import * as React from "react";
import { cn } from "../../lib/utils";

type MagneticProps = {
  children: React.ReactNode;
  className?: string;
  strength?: number;
};

function Magnetic({ children, className, strength = 14 }: MagneticProps): JSX.Element {
  const ref = React.useRef<HTMLDivElement>(null);
  const [transform, setTransform] = React.useState("translate3d(0, 0, 0)");

  const handleMove = (event: React.MouseEvent<HTMLDivElement>) => {
    if (typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      return;
    }
    const element = ref.current;
    if (!element) {
      return;
    }
    const rect = element.getBoundingClientRect();
    const offsetX = (event.clientX - rect.left) / rect.width - 0.5;
    const offsetY = (event.clientY - rect.top) / rect.height - 0.5;

    setTransform(`translate3d(${offsetX * strength}px, ${offsetY * strength}px, 0)`);
  };

  const reset = () => setTransform("translate3d(0, 0, 0)");

  return (
    <div
      ref={ref}
      className={cn("inline-flex transition-transform duration-200 ease-out", className)}
      style={{ transform }}
      onMouseMove={handleMove}
      onMouseLeave={reset}
    >
      {children}
    </div>
  );
}

export default Magnetic;
