import * as React from "react";
import { Project } from "../data/projects";
import { Badge } from "./ui/badge";
import { Button } from "./ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "./ui/card";
import TiltSurface from "./effects/TiltSurface";
import PixelCard from "./effects/PixelCard";
import ProjectModal from "./ProjectModal";

type ProjectsGridProps = {
  projects: Project[];
};

function ProjectsGrid({ projects }: ProjectsGridProps): JSX.Element {
  const [selectedProject, setSelectedProject] = React.useState<Project | null>(null);
  const [open, setOpen] = React.useState(false);

  const openModal = (project: Project) => {
    setSelectedProject(project);
    setOpen(true);
  };

  return (
    <>
      <div className="mt-6 grid gap-6 md:grid-cols-2">
        {projects.map((project) => (
          <TiltSurface key={project.slug} className="h-full">
            <PixelCard className="h-full">
              <Card className="glow-hover h-full overflow-hidden bg-[#081616]/75">
                <img
                  src={project.thumbnail}
                  alt={`Miniatura de ${project.title}`}
                  className="h-48 w-full border-b border-matrix-line object-cover"
                  loading="lazy"
                />

                <CardHeader>
                  <CardTitle className="matrix-heading text-2xl">{project.title}</CardTitle>
                  <CardDescription>{project.summary}</CardDescription>
                </CardHeader>

                <CardContent>
                  <div className="flex flex-wrap gap-2">
                    {project.stack.map((item) => (
                      <Badge key={`${project.slug}-${item}`} variant="muted">
                        {item}
                      </Badge>
                    ))}
                  </div>

                  <ul className="mt-4 space-y-2 text-sm text-matrix-muted">
                    {project.impact.map((metric) => (
                      <li key={`${project.slug}-${metric}`}>• {metric}</li>
                    ))}
                  </ul>
                </CardContent>

                <CardFooter className="flex-wrap">
                  {project.links.demo ? (
                    <a
                      href={project.links.demo}
                      target="_blank"
                      rel="noreferrer"
                      className="inline-flex h-9 items-center rounded-md border border-matrix-neon/45 bg-matrix-neon/10 px-3 text-xs text-matrix-text"
                    >
                      Demo
                    </a>
                  ) : null}
                  {project.links.github ? (
                    <a
                      href={project.links.github}
                      target="_blank"
                      rel="noreferrer"
                      className="inline-flex h-9 items-center rounded-md border border-matrix-line px-3 text-xs text-matrix-text"
                    >
                      GitHub
                    </a>
                  ) : null}
                  {project.links.caseStudy ? (
                    <a
                      href={project.links.caseStudy}
                      target="_blank"
                      rel="noreferrer"
                      className="inline-flex h-9 items-center rounded-md border border-matrix-cyan/40 bg-matrix-cyan/10 px-3 text-xs text-matrix-text"
                    >
                      Case Study
                    </a>
                  ) : null}

                  <Button variant="outline" size="sm" onClick={() => openModal(project)}>
                    Ver detalles
                  </Button>
                </CardFooter>
              </Card>
            </PixelCard>
          </TiltSurface>
        ))}
      </div>

      <ProjectModal project={selectedProject} open={open} onOpenChange={setOpen} />
    </>
  );
}

export default ProjectsGrid;
